/* picogit - shared declarations for the C core. */
#ifndef PICOGIT_H
#define PICOGIT_H

#include <stddef.h>
#include <stdint.h>

#include "lua.h"
#include "lauxlib.h"

#ifndef PICOGIT_VERSION
#define PICOGIT_VERSION "0.0.0"
#endif

/* Embedded Lua modules (generated by tools/embed.lua). */
struct pg_embedded_module {
    const char *name;
    const unsigned char *data;
    size_t len;
};
extern const struct pg_embedded_module pg_embedded_modules[];

/* Embedded CA bundle (generated by tools/mkcabundle.py): zlib-compressed
 * concatenation of DER certificates. */
extern const unsigned char pg_cabundle_z[];
extern const size_t pg_cabundle_z_len;
extern const size_t pg_cabundle_len;

int luaopen_picogit_core(lua_State *L);

/* Each file registers its functions into the table on top of the stack. */
void pg_register_zlib(lua_State *L);
void pg_register_sha1(lua_State *L);
void pg_register_fs(lua_State *L);
void pg_register_http(lua_State *L);
void pg_register_rand(lua_State *L);

/* Fill buf with n bytes from the kernel CSPRNG (getrandom, falling back to
 * /dev/urandom on kernels without it). Returns 0 on success. */
int pg_random(void *buf, size_t n);

/* Push "msg: strerror(errno)" style failure: nil, message, errno. */
int pg_fail(lua_State *L, const char *what);

/* Get the FILE* behind a Lua io file handle argument. */
#include <stdio.h>
FILE *pg_checkfile(lua_State *L, int idx);

#endif
